! Typed-handle wrappers, included into the module contains section.

    function rocblas_create_handle_typed(handle) result(create_handle)
      use, intrinsic :: iso_c_binding
      use hipfort_handles
      implicit none
      type(rocblas_handle_t) :: handle
      integer(kind(rocblas_status_success)) :: create_handle
      create_handle = rocblas_create_handle_(handle%ptr)
    end function rocblas_create_handle_typed

    function rocblas_destroy_handle_typed(handle) result(destroy_handle)
      use, intrinsic :: iso_c_binding
      use hipfort_handles
      implicit none
      type(rocblas_handle_t), value :: handle
      integer(kind(rocblas_status_success)) :: destroy_handle
      destroy_handle = rocblas_destroy_handle_(handle%ptr)
    end function rocblas_destroy_handle_typed

    function rocblas_set_stream_typed(handle, stream) result(set_stream)
      use, intrinsic :: iso_c_binding
      use hipfort_handles
      implicit none
      type(rocblas_handle_t), value :: handle
      type(c_ptr), value :: stream
      integer(kind(rocblas_status_success)) :: set_stream
      set_stream = rocblas_set_stream_(handle%ptr, stream)
    end function rocblas_set_stream_typed

    function rocblas_get_stream_typed(handle, stream) result(get_stream)
